package com.witchersbestiary.client.fist;
import com.witchersbestiary.fist.*;import net.minecraft.client.*;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import net.minecraft.text.Text;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;
public final class FistClient{
 private static FistPackets.State state;
 private record TrackedPose(FistPackets.Pose value,long received){}
 private static final java.util.Map<Integer,TrackedPose> poses=new java.util.HashMap<>();
 public static FistPackets.Pose pose(int entity){var c=MinecraftClient.getInstance();var p=poses.get(entity);if(p==null||c.world==null||c.world.getTime()-p.received()>40){poses.remove(entity);return null;}return new FistPackets.Pose(entity,true,p.value().action(),p.value().ticks()+(int)(c.world.getTime()-p.received()));}
private static boolean blocking,attackHeld;
 private static KeyBinding heavy,block,dodge;
 public static FistPackets.State status(){return state;}
 private static void send(FistFightSession.Action action){if(DuelClient.view()!=null){DuelClient.input(action);return;}net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new FistPackets.Action(action.ordinal()));}
 public static void initialize(){DuelClient.initialize();TournamentScreen.initialize();net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.registerGlobalReceiver(FistPackets.Pose.ID,(p,c)->c.client().execute(()->{if(!p.active())poses.remove(p.player());else if(c.client().world!=null){if(poses.size()>128)poses.clear();poses.put(p.player(),new TrackedPose(p,c.client().world.getTime()));}}));
  heavy=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.fist_heavy",InputUtil.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_H,"category.witchersbestiary.fist"));block=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.fist_block",InputUtil.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_J,"category.witchersbestiary.fist"));dodge=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.fist_dodge",InputUtil.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_K,"category.witchersbestiary.fist"));
  net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.registerGlobalReceiver(FistPackets.State.ID,(s,c)->c.client().execute(()->{if(!s.active()||state!=null&&state.stage()>0&&s.stage()==0)blocking=false;state=s.active()?s:null;}));
  net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents.DISCONNECT.register((h,c)->{state=null;blocking=false;poses.clear();});net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientWorldEvents.AFTER_CLIENT_WORLD_CHANGE.register((c,w)->{state=null;blocking=false;poses.clear();});
  net.fabricmc.fabric.api.event.player.AttackBlockCallback.EVENT.register((p,w,h,pos,direction)->w.isClient&&state!=null?net.minecraft.util.ActionResult.FAIL:net.minecraft.util.ActionResult.PASS);
  net.fabricmc.fabric.api.event.player.AttackEntityCallback.EVENT.register((p,w,h,e,hit)->{if(w.isClient&&state!=null){send(FistFightSession.Action.QUICK);return net.minecraft.util.ActionResult.FAIL;}return net.minecraft.util.ActionResult.PASS;});
  net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents.END_CLIENT_TICK.register(c->{if(state==null||c.player==null)return;if(c.currentScreen==null){boolean pressed=c.options.attackKey.isPressed();if(pressed&&!attackHeld)send(FistFightSession.Action.QUICK);attackHeld=pressed;while(heavy.wasPressed())send(FistFightSession.Action.HEAVY);while(dodge.wasPressed())send(FistFightSession.Action.DODGE);}boolean held=block.isPressed()&&c.currentScreen==null;if(held&&c.player.age%4==0)send(FistFightSession.Action.BLOCK);if(held!=blocking){blocking=held;send(held?FistFightSession.Action.BLOCK:FistFightSession.Action.IDLE);}});
  net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback.EVENT.register((ctx,tick)->{if(state==null)return;var c=MinecraftClient.getInstance();if(c.currentScreen!=null||c.options.hudHidden)return;var bounds=FistHudSettings.bounds(c.getWindow().getScaledWidth(),c.getWindow().getScaledHeight());ctx.getMatrices().push();ctx.getMatrices().translate(bounds[0],bounds[1],0);float scale=bounds[4]/10000f;ctx.getMatrices().scale(scale,scale,1);int width=210,x=4,y=4;boolean hints=c.getWindow().getScaledHeight()>=240;ctx.fill(x-4,y-4,x+width+4,y+(hints?84:DuelClient.view()!=null||TournamentScreen.hud()!=null?60:48),0xc0201814);var title=Text.translatable(state.name());ctx.drawText(c.textRenderer,c.textRenderer.trimToWidth(title.getString(),width),x,y,0xffe6ca9a,false);ctx.drawText(c.textRenderer,Text.translatable("fist.witchersbestiary.status",state.stage()>0?Text.literal(""+state.stage()):Text.translatable("fist.witchersbestiary.action."+state.action().toLowerCase(java.util.Locale.ROOT))),x,y+12,0xffe6ca9a,false);ctx.fill(x,y+25,x+width,y+34,0xff45342b);ctx.fill(x,y+25,x+(int)(width*Math.clamp(state.stamina()/Math.max(1,state.maxStamina()),0,1)),y+34,0xff4198ab);ctx.drawText(c.textRenderer,Text.translatable("fist.witchersbestiary.stamina",(int)state.stamina()),x+2,y+25,0xffffffff,true);ctx.drawText(c.textRenderer,Text.translatable("fist.witchersbestiary.health",(int)state.playerHealth(),(int)state.health()),x,y+37,0xfff0d49d,false);if(hints){var lines=c.textRenderer.wrapLines(Text.translatable("fist.witchersbestiary.controls",heavy.getBoundKeyLocalizedText(),block.getBoundKeyLocalizedText(),dodge.getBoundKeyLocalizedText()),width);for(int i=0;i<Math.min(3,lines.size());i++)ctx.drawText(c.textRenderer,lines.get(i),x,y+49+i*9,0xffc4b09c,false);}if(TournamentScreen.hud()!=null)ctx.drawText(c.textRenderer,TournamentScreen.hud(),x,y+(hints?76:49),0xffe6ca9a,false);if(DuelClient.view()!=null){ctx.drawText(c.textRenderer,DuelClient.view().stage().equals("FINISHED")?DuelClient.status():DuelClient.menuHint(),x,y+(hints?76:49),0xffe6ca9a,false);}ctx.getMatrices().pop();});
  net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry.register(FistRegistry.ROCK_TROLL,c->new FistRenderer(c,true));
  for(var type:java.util.List.of(FistRegistry.NOVICE,FistRegistry.EXPERIENCED,FistRegistry.CHAMPION))net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry.register(type,FistRenderer::new);
 }
}
